mapper.select:
/* 사용자 관리 (7010) */
/* AdminUserMapper.selectOne */
SELECT AI_INPT_USER_ENO FROM CSPD101TI WHERE AI_INPT_USER_ENO = #{aiInptUserEno}

/* 사용자 관리 (7010) */ /* AdminUserMapper.selectListTotCnt */
SELECT COUNT(*) totcnt FROM( SELECT ROW_NUMBER()OVER(PARTITION BY AI_INPT_USER_ENO ORDER BY AI_INPT_USER_ID DESC) AS ORDERR, AI_INPT_USER_ID, AI_INPT_AUT_CD, AI_INPT_USER_FA_RE_YN, AI_INPT_USER_ENO, AI_INPT_USER_NM, AI_INPT_SNPE_ENO, AI_INPT_USER_YN, AI_INPT_MGPE_YN, AI_INPT_USER_RGS_DTM, AI_INPT_USER_END_DTM, LST_DB_CHG_ID, TRN_LOG_SRNO, LST_DB_CHG_DTM, AI_INPT_SRVC_USER_DSCD, (SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '120' AND AI_INPT_CMN_CD = A.AI_INPT_AUT_CD) AS AI_INPT_USER_AUT_VAL, (SELECT AI_INPT_USER_NM FROM CSPD101TI WHERE AI_INPT_USER_ENO = A.AI_INPT_SNPE_ENO AND ROWNUM = 1 ) AS AI_INPT_SNPE_NM FROM CSPD101TI A WHERE 1=1
)C WHERE C.ORDERR = '1'

		/* 사용자 관리 (7010) */
		/* AdminUserMapper.selectListTotCnt */
		 SELECT A.* from(
 			SELECT AI_INPT_USER_NM,AI_INPT_USER_ENO
                FROM CSPD101TI     
                WHERE AI_INPT_AUT_CD = #{schAuth}
                ) A

  				WHERE CONCAT(AI_INPT_USER_NM,
                AI_INPT_USER_ENO) like '%' || #{schUserNm} || '%'

mapper.update:
/* 사용자 관리 (7010) */
/* AdminUserMapper.userUpdate */
UPDATE CSPD101TI SET
	 AI_INPT_SNPE_ENO = #{aiInptSnpeEno}
	, AI_INPT_MGPE_YN = NVL(#{aiInptAdminYn},'N')
	, AI_INPT_USER_YN = #{aiInptUserYn} 
	, LST_DB_CHG_ID = #{lstDbChgId}
	, TRN_LOG_SRNO = #{trnLogSrno}
	, LST_DB_CHG_DTM = TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS')
	, AI_INPT_AUT_CD = #{aiInptUserAutCd}
	, AI_INPT_SRVC_USER_DSCD = #{aiInptSrvcUserDscd}
WHERE AI_INPT_USER_ID = #{aiInptUserId}

/* 사용자 관리 (7010) */
/* AdminUserMapper.userDelete */
DELETE FROM CSPD101TI WHERE AI_INPT_USER_ID = #{aiInptUserId}
